def sort_records(records):
    records.sort(key=lambda r: r['ts'])
    return records

def saturate(values, cap):
    for i, v in enumerate(values):
        if v > cap:
            values[i] = cap
    return values

def with_discounts(cart):
    for item in cart:
        item['price'] *= 0.9
    return cart
